     1	import { Notification } from "../domain/notification";
     2	import { CustomerRepository } from "../repository/customerRepository";
     3	import { PendingEvent } from "../repository/orderRepository";
     4	
     5	export interface Plan {
     6	  notifications: Notification[];
     7	  skippedOptOut: number;
     8	}
     9	
    10	/**
    11	 * 회차에 실린 주문 이벤트를 고객 알림으로 바꾼다.
    12	 *  - 수신 거부 고객은 제외한다.
    13	 *  - 같은 주문·같은 이벤트가 회차 안에 여러 번 기록됐으면(운영자 재입력 등) 한 번만 알린다.
    14	 *  - 이벤트 기록 순서를 유지한다.
    15	 */
    16	export function planNotifications(events: PendingEvent[], customers: CustomerRepository): Plan {
    17	  const seen = new Set<string>();
    18	  const notifications: Notification[] = [];
    19	  let skippedOptOut = 0;
    20	  for (const e of [...events].sort((a, b) => a.seq - b.seq)) {
    21	    const customer = customers.find(e.customerId);
    22	    if (!customer || !customer.smsOptIn) {
    23	      skippedOptOut++;
    24	      continue;
    25	    }
    26	    const id = `${e.orderNo}#${e.kind}`;
    27	    if (seen.has(id)) continue;
    28	    seen.add(id);
    29	    notifications.push({ orderNo: e.orderNo, customerId: e.customerId, kind: e.kind });
    30	  }
    31	  return { notifications, skippedOptOut };
    32	}
