     1	import { DeliveredAlert } from "../domain/notification";
     2	import { OrderEventKind } from "../domain/order";
     3	import { MqpubClient } from "../messaging/mqpubClient";
     4	import { decodePayload } from "../messaging/payloadCodec";
     5	import { CustomerRepository } from "../repository/customerRepository";
     6	import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
     7	import { SmsGateway } from "./smsGateway";
     8	import { renderAlert } from "./templates";
     9	
    10	export interface DrainResult {
    11	  read: number;
    12	  delivered: DeliveredAlert[];
    13	  failed: { orderNo: string; kind: OrderEventKind; reason: string }[];
    14	}
    15	
    16	/**
    17	 * 알림 토픽 소비자. 마지막으로 읽은 위치 다음부터 읽어 문자를 보낸다.
    18	 * 같은 키가 다시 전달되면(재처리·재기동) 두 번 보내지 않는다.
    19	 */
    20	export class AlertConsumer {
    21	  private nextOffset = 0;
    22	  private readonly handledKeys = new Set<string>();
    23	
    24	  constructor(
    25	    private readonly client: MqpubClient,
    26	    private readonly topic: string,
    27	    private readonly customers: CustomerRepository,
    28	    private readonly gateway: SmsGateway,
    29	    private readonly log: DeliveryLogRepository,
    30	    private readonly senderId: string,
    31	    private readonly limit: number,
    32	  ) {}
    33	
    34	  position(): number {
    35	    return this.nextOffset;
    36	  }
    37	
    38	  drain(runId: number): DrainResult {
    39	    const rows = this.client.consume(this.topic, this.nextOffset).slice(0, this.limit);
    40	    const result: DrainResult = { read: rows.length, delivered: [], failed: [] };
    41	    for (const row of rows) {
    42	      this.nextOffset = row.offset + 1;
    43	      if (this.handledKeys.has(row.key)) continue;
    44	      this.handledKeys.add(row.key);
    45	
    46	      const n = decodePayload(row.payload);
    47	      if (!n) {
    48	        result.failed.push({ orderNo: "?", kind: "PAID", reason: "bad-payload" });
    49	        continue;
    50	      }
    51	      const customer = this.customers.find(n.customerId);
    52	      if (!customer) {
    53	        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: "unknown-customer" });
    54	        continue;
    55	      }
    56	      const receipt = this.gateway.send(this.senderId, customer.phone, renderAlert(n.kind, customer.name, n.orderNo));
    57	      if (!receipt.ok) {
    58	        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: receipt.reason ?? "sms-failed" });
    59	        continue;
    60	      }
    61	      const d: DeliveredAlert = {
    62	        runId,
    63	        orderNo: n.orderNo,
    64	        customerId: n.customerId,
    65	        kind: n.kind,
    66	        phone: customer.phone,
    67	        receiptId: receipt.receiptId ?? "",
    68	      };
    69	      this.log.append(d);
    70	      result.delivered.push(d);
    71	    }
    72	    return result;
    73	  }
    74	}
