   125	type Fn = () => void | Promise<void>;
   126	const registered: [string, Fn][] = [];
   127	const cleanups: (() => void)[] = [];
   128	
   129	export function test(name: string, fn: Fn): void {
   130	  registered.push([name, fn]);
   131	}
   132	
   133	export function onCleanup(fn: () => void): void {
   134	  cleanups.push(fn);
   135	}
   136	
   137	export function eq(actual: unknown, expected: unknown, label: string): void {
   138	  const a = JSON.stringify(actual);
   139	  const e = JSON.stringify(expected);
   140	  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
   141	}
   142	
   143	export async function run(): Promise<void> {
   144	  let failed = 0;
   145	  for (const [name, fn] of registered) {
   146	    try {
   147	      await fn();
   148	      console.log(`ok   - ${name}`);
   149	    } catch (e) {
   150	      failed++;
   151	      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
   152	    }
   153	  }
   154	  for (const c of cleanups) {
   155	    try { c(); } catch { /* ignore */ }
   156	  }
   157	  console.log(failed === 0 ? "all passed" : `${failed} failed`);
   158	  process.exitCode = failed === 0 ? 0 : 1;
   159	}
